  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 21, $j$6.1 Writing the Literary Analysis$j$, $j${"readings": [{"title": "Proverbs 25 (King James Version)", "url": "/portal/bible/Proverbs/25"}], "body": "A literary analysis explains how a text works and what it means. It does not retell the story; it makes a claim about the text and proves it with evidence.\n\nParts of a literary analysis essay:\n1. Introduction: a hook, background (title, author, subject) and a thesis.\n2. Body paragraphs: each begins with a topic sentence that supports the thesis, then gives evidence (quotation or detail), then explains how the evidence supports the claim.\n3. Conclusion: restates the thesis in a fresh way and tells why it matters.\n\nThe thesis is a debatable claim about the text. Weak thesis: The poem is about morning. Strong thesis: In the poem, the morning is pictured as a patient hand, which teaches readers to see each day as a gift of mercy.\n\nUse the PIE pattern in each body paragraph:\nP: Point (topic sentence).\nI: Illustration (quotation or specific detail).\nE: Explanation (how it proves the point).\n\nUse transitions to connect ideas: first, however, in addition, for example, as a result, finally.\n\nIntegrate quotations smoothly. Introduce them with a phrase: The narrator observes that, The poem states, According to the passage.\n\nRead this original PIE paragraph:\n\nThe lantern in the allegory stands for the human heart. The author writes that the traveler carried a lantern with a cracked glass. The crack, which weakens the light, suggests a hidden fault that dims a person's goodness. This detail shows that the author wants readers to look inward before blaming the wind.\n\nHabakkuk 2:2 says, Write the vision, and make it plain upon tables, that he may run that readeth it. Clear writing helps readers run with the message.\n\nYour task: (1) Write a strong thesis for a short poem or passage you have read. (2) Write one PIE paragraph supporting it. (3) Add two transitions.\n\nFlorida standards: ELA.11.C.1.3, ELA.11.C.1.4, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.C.1.3, ELA.11.C.1.4, ELA.K12.EE.1.1", "script": "Welcome to the final unit. Now we turn from reading to writing. A literary analysis explains how a text works and what it means. It does not retell the story. It makes a claim about the text and proves that claim with evidence.\n\nListen to the parts. The introduction has a hook, some background such as the title, author and subject, and a thesis. The body paragraphs each begin with a topic sentence that supports the thesis, then give evidence, such as a quotation or a detail, and then explain how that evidence supports the claim. The conclusion restates the thesis in a fresh way and tells why it matters.\n\nNow watch this. The thesis is a debatable claim. A weak thesis says, the poem is about morning. A strong thesis says, in the poem the morning is pictured as a patient hand, which teaches readers to see each day as a gift of mercy. See the difference? The strong thesis has something to prove.\n\nUse the PIE pattern in each body paragraph. P is Point, your topic sentence. I is Illustration, a quotation or specific detail. E is Explanation, how it proves the point. And use transitions like first, however, in addition, for example, as a result and finally.\n\nIntegrate quotations smoothly. Introduce them with a phrase like the narrator observes that, or the poem states, or according to the passage.\n\nHere is an original PIE paragraph. The lantern in the allegory stands for the human heart. The author writes that the traveler carried a lantern with a cracked glass. The crack, which weakens the light, suggests a hidden fault that dims a person's goodness. This detail shows that the author wants readers to look inward before blaming the wind.\n\nAnd Habakkuk chapter two, verse two says, Write the vision, and make it plain upon tables, that he may run that readeth it. Clear writing helps readers run with the message.\n\nYour task today. Write a strong thesis for a short poem or passage you have read. Write one PIE paragraph supporting it. And add two transitions. Take the four question check when you finish.\n\nWrite clearly, and write truthfully. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.1 Writing the Literary Analysis$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 22, $j$6.2 Narrative Writing with Multiple Viewpoints$j$, $j${"readings": [{"title": "Habakkuk 2 (King James Version)", "url": "/portal/bible/Habakkuk/2"}], "body": "A narrative with multiple viewpoints tells the same event through the eyes of more than one character. This technique shows how people can understand the same moment differently and gives readers a fuller picture.\n\nElements of a complex narrative:\n1. Characters with clear wants and fears.\n2. A setting that affects the action.\n3. A plot with conflict, rising action, climax and resolution.\n4. Dialogue that sounds natural.\n5. Sensory details and figurative language.\n6. A theme that grows from the events.\n\nTechniques for multiple viewpoints:\n1. Alternate sections by narrator, labeling each section with the narrator's name.\n2. Keep each voice distinct through word choice and tone.\n3. Show how each character's background changes what he or she notices.\n\nStandard English conventions matter in narrative: use correct verb tense, punctuate dialogue with quotation marks, begin a new paragraph for each new speaker, and avoid fragments and run on sentences unless used on purpose for effect.\n\nRead this original short example:\n\nNora: The storm took the porch light before supper. I held my brother's hand and counted the seconds between the thunder and the flash.\n\nEli: Nora thinks I was afraid. I was not afraid. I was listening to the wind, because Dad says you can hear a storm change its mind.\n\nAnalysis: The same event is told by two siblings. Nora notices counting and holding; Eli notices listening and wisdom. Their voices differ in tone, and the theme shows how fear and curiosity can sit side by side.\n\nColossians 4:6 says, Let your speech be alway with grace, seasoned with salt, that ye may know how ye ought to answer every man.\n\nYour task: (1) Write a short narrative of at least 100 words with two viewpoints about one event. (2) Label each section. (3) Check your punctuation for dialogue and verb tense.\n\nFlorida standards: ELA.11.C.1.2, ELA.11.C.3.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.C.1.2, ELA.11.C.3.1", "script": "Now we explore narrative writing. A narrative with multiple viewpoints tells the same event through the eyes of more than one character. This technique shows how people can understand the same moment differently, and it gives readers a fuller picture.\n\nListen to the elements of a complex narrative. Characters with clear wants and fears. A setting that affects the action. A plot with conflict, rising action, climax and resolution. Dialogue that sounds natural. Sensory details and figurative language. And a theme that grows from the events.\n\nNow watch this. To handle multiple viewpoints, alternate sections by narrator and label each section with the narrator's name. Keep each voice distinct through word choice and tone. And show how each character's background changes what he or she notices.\n\nDo not forget conventions. Use correct verb tense. Punctuate dialogue with quotation marks. Begin a new paragraph for each new speaker. And avoid fragments and run on sentences unless you use them on purpose for effect.\n\nLet us read an original short example. Nora says, the storm took the porch light before supper. I held my brother's hand and counted the seconds between the thunder and the flash. Then Eli says, Nora thinks I was afraid. I was not afraid. I was listening to the wind, because Dad says you can hear a storm change its mind.\n\nThe same event is told by two siblings. Nora notices counting and holding. Eli notices listening and wisdom. Their voices differ in tone. And the theme shows how fear and curiosity can sit side by side.\n\nColossians chapter four, verse six says, Let your speech be alway with grace, seasoned with salt, that ye may know how ye ought to answer every man.\n\nYour task today. Write a short narrative of at least one hundred words with two viewpoints about one event. Label each section. And check your punctuation for dialogue and your verb tense. Take the four question check when you finish.\n\nEvery person sees a different part of the picture, and wisdom listens to all. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.2 Narrative Writing with Multiple Viewpoints$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 23, $j$6.3 Research: Primary and Secondary Sources$j$, $j${"readings": [{"title": "Colossians 4 (King James Version)", "url": "/portal/bible/Colossians/4"}], "body": "A literary research project combines primary and secondary sources to support a claim about a text or an author.\n\nA primary source is an original work or a firsthand record: a poem, a speech, a letter, a diary, a photograph or an interview. A secondary source is a work that discusses or interprets primary sources: a biography, a critical article, a textbook or an encyclopedia.\n\nSteps in research:\n1. Choose a topic and narrow it to a question.\n2. Find reliable sources. Check the author, the date, the publisher and the purpose. Websites ending in .edu or .gov and well known libraries are often reliable. Be careful with anonymous or opinion pages.\n3. Take notes. Record quotations exactly and paraphrase (put ideas in your own words) with care.\n4. Cite your sources. Give credit to the original author so that readers can find the sources and so that you avoid plagiarism, which means presenting another person's words or ideas as your own.\n5. Revise using feedback and digital editing tools such as spell check, comments, tracked changes and shared documents.\n\nA simple citation list names the author, the title, the publisher or website and the date.\n\nExample research question: How did the poems of the Harlem Renaissance express hope?\nPrimary source: a poem from the period.\nSecondary source: a scholar's article on the movement.\n\nProverbs 14:15 says, The simple believeth every word: but the prudent man looketh well to his going. A good researcher checks every source carefully.\n\nYour task: (1) Write a research question about an author or movement from this course. (2) Name one primary and one secondary source you could use. (3) Explain two ways to check that a source is reliable.\n\nFlorida standards: ELA.11.C.4.1, ELA.K12.EE.1.1, ELA.11.C.1.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.C.4.1, ELA.K12.EE.1.1, ELA.11.C.1.5", "script": "Today we learn to research like a scholar. A literary research project combines primary and secondary sources to support a claim about a text or an author.\n\nA primary source is an original work or a firsthand record. A poem, a speech, a letter, a diary, a photograph or an interview. A secondary source is a work that discusses or interprets primary sources. A biography, a critical article, a textbook or an encyclopedia.\n\nListen to the steps. First, choose a topic and narrow it to a question. Second, find reliable sources. Check the author, the date, the publisher and the purpose. Websites ending in dot edu or dot gov and well known libraries are often reliable. Be careful with anonymous or opinion pages. Third, take notes. Record quotations exactly, and paraphrase carefully, which means putting ideas in your own words. Fourth, cite your sources. Give credit to the original author so readers can find the sources and so you avoid plagiarism. Plagiarism means presenting another person's words or ideas as your own. And fifth, revise using feedback and digital editing tools such as spell check, comments, tracked changes and shared documents.\n\nNow watch this. A simple citation names the author, the title, the publisher or website, and the date.\n\nHere is an example research question. How did the poems of the Harlem Renaissance express hope? A primary source would be a poem from the period. A secondary source would be a scholar's article on the movement.\n\nProverbs chapter fourteen, verse fifteen says, The simple believeth every word: but the prudent man looketh well to his going. A good researcher checks every source carefully.\n\nYour task today. Write a research question about an author or movement from this course. Name one primary and one secondary source you could use. And explain two ways to check that a source is reliable. Take the four question check when you finish.\n\nHonest research honors the truth and the people who found it first. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.3 Research: Primary and Secondary Sources$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 Presenting Your Work with Confidence$j$, $j${"readings": [{"title": "Proverbs 15 (King James Version)", "url": "/portal/bible/Proverbs/15"}], "body": "An oral presentation shares your research or ideas with an audience. A strong presentation has a clear purpose, a logical order, confident delivery and helpful visuals.\n\nParts of an effective presentation:\n1. Opening: a hook, your topic and your main point.\n2. Body: two or three key points, each with evidence and an example.\n3. Closing: a summary and a call to think or act.\n\nDelivery skills:\n1. Eye contact: look at your audience, not only at your notes.\n2. Voice: speak clearly and at a steady pace; use pauses for emphasis.\n3. Posture and gestures: stand tall, and use natural movements.\n4. Preparation: practice aloud several times and time yourself.\n\nDigital presentation tips:\n1. Use short phrases, not paragraphs, on slides.\n2. Use readable fonts, strong contrast and a consistent design.\n3. Add images, charts or short audio only when they support your point.\n4. Credit the sources of images and information.\n5. Do not read slides word for word; speak to the audience.\n\nCollaborative discussion skills: listen carefully, build on others' ideas, disagree respectfully, and support your view with evidence.\n\nPolished writing for an audience uses an appropriate voice and tone, correct conventions and multimedia where helpful. Match your style to your audience: formal for a class report, warmer for a community talk.\n\nProverbs 25:11 says, A word fitly spoken is like apples of gold in pictures of silver. Colossians 4:6 reminds us that our speech should be gracious.\n\nYour task: (1) Plan a three minute presentation on an author or movement from this course. (2) List your opening, three key points and closing. (3) Name two ways your slides will help rather than distract.\n\nFlorida standards: ELA.11.C.2.1, ELA.11.C.5.1, ELA.11.C.5.2, ELA.K12.EE.4.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.C.2.1, ELA.11.C.5.1, ELA.11.C.5.2, ELA.K12.EE.4.1", "script": "Now we prepare to speak. An oral presentation shares your research or ideas with an audience. A strong presentation has a clear purpose, a logical order, confident delivery and helpful visuals.\n\nListen to the parts. The opening has a hook, your topic and your main point. The body has two or three key points, each with evidence and an example. The closing gives a summary and a call to think or act.\n\nNow watch this. Delivery matters. Make eye contact, and look at your audience, not only at your notes. Speak clearly at a steady pace, and use pauses for emphasis. Stand tall, and use natural gestures. And practice aloud several times, and time yourself.\n\nFor a digital presentation, use short phrases, not paragraphs, on your slides. Use readable fonts, strong contrast and a consistent design. Add images, charts or short audio only when they support your point. Credit the sources of images and information. And never read your slides word for word. Speak to the people in front of you.\n\nIn group discussion, listen carefully, build on others' ideas, disagree respectfully, and support your view with evidence.\n\nWhen you write for an audience, match your style. Use a formal voice for a class report, and a warmer voice for a community talk. Always check your conventions.\n\nProverbs chapter twenty five, verse eleven says, A word fitly spoken is like apples of gold in pictures of silver. And Colossians chapter four reminds us that our speech should be gracious.\n\nYour task today. Plan a three minute presentation on an author or movement from this course. List your opening, three key points and closing. And name two ways your slides will help rather than distract. Take the four question check when you finish.\n\nSpeak with confidence, because you carry something worth hearing. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 Presenting Your Work with Confidence$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: Short Literary Analysis Essay$j$, $j${"prompt": "Write a literary analysis essay of at least 250 words using this original poem.\n\nEven the stars were once afraid of the dark.\nThey lit one small fire, then another,\nand trusted that the night was only a road.\nNow the whole sky is a lamp for travelers,\nand no one asks who struck the first spark.\n\nYour essay must include: (1) an introduction with a hook, the poem's subject and a thesis that makes a claim about the poem's meaning; (2) two body paragraphs, each using the PIE pattern (point, illustration with a quotation, explanation); (3) at least two figurative language techniques named and explained (for example, personification, metaphor or imagery); (4) a conclusion that restates the thesis freshly and tells why the poem matters; (5) a connection to Scripture, such as John 1:5, which says, And the light shineth in darkness; and the darkness comprehended it not; (6) transitions, correct grammar and punctuation, and a respectful academic voice.", "rubric": "100 points. Introduction and strong thesis: 15 points. Two PIE body paragraphs with quotations: 30 points. Figurative language explained: 15 points. Conclusion: 10 points. Scripture connection: 10 points. Transitions, grammar and conventions: 15 points. Length of at least 250 words: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: Short Literary Analysis Essay$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: Your Voice in the Conversation$j$, $j${"prompt": "You have studied many American voices this year. Write a post of at least 120 words that (1) explains which author, speech or poem from this course taught you the most and why, (2) describes how you plan to use your own voice, in writing or speaking, to serve your family, church or community, (3) names one writing or speaking skill you want to keep improving, and (4) connects your answer to Colossians 4:6, which says, Let your speech be alway with grace, seasoned with salt, that ye may know how ye ought to answer every man. Then write a respectful reply of at least 40 words to another student, or answer this question: How can a person speak the truth and still show grace? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: Your Voice in the Conversation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 26, $j$Check 6.1: Writing the Literary Analysis$j$, $j${"questions": [{"q": "A strong thesis for a literary analysis is:", "options": ["A plot summary", "A title", "A debatable claim about the text", "A list of characters"]}, {"q": "In the PIE pattern, I stands for:", "options": ["Introduction", "Illustration", "Imagery", "Idea"]}, {"q": "The conclusion should:", "options": ["Add a new topic", "Repeat the introduction word for word", "End without a point", "Restate the thesis freshly and tell why it matters"]}, {"q": "A transition word such as however:", "options": ["Connects ideas", "Ends the essay", "Is a title", "Is a quotation"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Writing the Literary Analysis$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,3,0}'::int[], array[$j$A thesis makes a claim that needs proof.$j$,$j$I is the quotation or detail.$j$,$j$A conclusion restates and shows significance.$j$,$j$Transitions link ideas together.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Writing the Literary Analysis$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 27, $j$Check 6.2: Narrative Writing with Multiple Viewpoints$j$, $j${"questions": [{"q": "A narrative with multiple viewpoints:", "options": ["Uses only dates", "Has no characters", "Is always a poem", "Tells an event through more than one character's eyes"]}, {"q": "Dialogue should be punctuated with:", "options": ["Quotation marks", "Parentheses only", "Nothing", "Hash marks"]}, {"q": "A new paragraph begins:", "options": ["Every word", "Only at the end", "When a new speaker talks", "Never"]}, {"q": "Sensory details help the reader:", "options": ["Find the author's name", "Skip the story", "Count the pages", "See, hear, smell, taste or feel the scene"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Narrative Writing with Multiple Viewpoints$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,2,3}'::int[], array[$j$Multiple viewpoints show different perspectives.$j$,$j$Quotation marks mark spoken words.$j$,$j$Start a new paragraph for each new speaker.$j$,$j$Sensory details bring a scene to life.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Narrative Writing with Multiple Viewpoints$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 28, $j$Check 6.3: Research: Primary and Secondary Sources$j$, $j${"questions": [{"q": "A primary source is:", "options": ["An index", "A glossary", "A summary written by someone else", "An original work or firsthand record"]}, {"q": "Plagiarism is:", "options": ["Using a dictionary", "Quoting with credit", "Writing a summary with a citation", "Presenting another person's words or ideas as your own"]}, {"q": "To paraphrase is to:", "options": ["Skip the idea", "Put ideas in your own words", "Change the author", "Copy exactly"]}, {"q": "A reliable source usually has:", "options": ["Only opinions", "No author or date", "Only pictures", "A known author, a date and a clear purpose"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Research: Primary and Secondary Sources$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,1,3}'::int[], array[$j$A primary source is the original material.$j$,$j$Plagiarism means taking credit for someone else's work.$j$,$j$Paraphrasing restates the idea in new words.$j$,$j$Check author, date and purpose.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Research: Primary and Secondary Sources$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: Presenting Your Work with Confidence$j$, $j${"questions": [{"q": "A strong opening includes:", "options": ["Nothing", "Only the closing", "A hook, the topic and the main point", "Only an apology"]}, {"q": "Good slides use:", "options": ["Tiny fonts", "No design at all", "Short phrases and readable design", "Long paragraphs"]}, {"q": "Eye contact helps a speaker:", "options": ["Stay silent", "Connect with the audience", "Read faster", "Hide from the audience"]}, {"q": "When you use an image from another source, you should:", "options": ["Remove all text", "Credit the source", "Pretend it is yours", "Hide the file"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Presenting Your Work with Confidence$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,1,1}'::int[], array[$j$An opening grabs attention and states the point.$j$,$j$Short, readable slides help the audience.$j$,$j$Eye contact builds connection.$j$,$j$Credit the sources of images and information.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Presenting Your Work with Confidence$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 30, $j$Unit Quiz 6: Writing, Research and Presentation$j$, $j${"questions": [{"q": "A thesis is:", "options": ["The main claim of an essay", "A title", "A quotation", "The last sentence"]}, {"q": "In a PIE paragraph, E stands for:", "options": ["Ending", "Explanation", "Event", "Example"]}, {"q": "A secondary source:", "options": ["Is the original work", "Discusses or interprets primary sources", "Is a photograph only", "Is a diary only"]}, {"q": "To avoid plagiarism you should:", "options": ["Hide the source", "Change the title only", "Cite your sources", "Copy and say nothing"]}, {"q": "A narrative with multiple viewpoints:", "options": ["Is a list", "Has one speaker only", "Has no plot", "Tells an event through more than one character"]}, {"q": "Strong slides use:", "options": ["Short phrases and clear design", "Random colors", "Tiny fonts", "Long paragraphs"]}, {"q": "An effective closing:", "options": ["Apologizes", "Summarizes and gives a final thought", "Ends mid sentence", "Adds a new topic"]}, {"q": "Colossians 4:6 says our speech should be:", "options": ["Alway with grace, seasoned with salt", "Silent always", "Careless", "Harsh and loud"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Writing, Research and Presentation$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,2,3,0,1,0}'::int[], array[$j$The thesis states the main claim.$j$,$j$E is Explanation.$j$,$j$Secondary sources analyze primary sources.$j$,$j$Cite your sources.$j$,$j$It shows different perspectives.$j$,$j$Keep slides short and readable.$j$,$j$A closing sums up and leaves a final thought.$j$,$j$Colossians 4:6 says let your speech be alway with grace, seasoned with salt.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Writing, Research and Presentation$j$ on conflict (item_id) do nothing;
